class ChainHashMap:
    def __init__(self, capacity=8):
        self.m = capacity
        self.buckets = [[] for _ in range(self.m)]
        self.n = 0

    def _idx(self, key):
        return hash(key) % self.m

    def put(self, key, value):
        b = self.buckets[self._idx(key)]
        for pair in b:                    # update in place if key exists
            if pair[0] == key:
                pair[1] = value
                return
        b.append([key, value])            # append handles collisions
        self.n += 1
        if self.n / self.m > 0.75:        # load factor budget
            self._resize(2 * self.m)

    def get(self, key, default=None):
        for pair in self.buckets[self._idx(key)]:
            if pair[0] == key:
                return pair[1]
        return default

    def _resize(self, m):
        old = self.buckets
        self.m, self.n = m, 0
        self.buckets = [[] for _ in range(m)]
        for b in old:
            for k, v in b:
                self.put(k, v)            # rehash everything

